import * as OurXmlization from "../src/xmlization";
import * as OurTypes from "../src/types";

import * as TestCommonXmlization from "./commonXmlization";

test(
  "IItem XML round-trip " +
  "starting from Box OK",
  () => {
    const instance = TestCommonXmlization.loadMinimalBox();

    const xmlText = OurXmlization.toXmlString(instance);
    const anotherInstanceOrError = OurXmlization.fromXmlString(xmlText);
    expect(anotherInstanceOrError.error).toBeNull();
    const anotherInstance = anotherInstanceOrError.mustValue();

    const asInterface = OurTypes.asItem(anotherInstance);
    expect(asInterface).not.toBeNull();
  }
);

test(
  "IItem XML round-trip via " +
  "itemFromXmlString starting from Box OK",
  () => {
    const instance = TestCommonXmlization.loadMinimalBox();

    const xmlText = OurXmlization.toXmlString(instance);
    const anotherInstanceOrError = OurXmlization.itemFromXmlString(
      xmlText
    );
    expect(anotherInstanceOrError.error).toBeNull();
  }
);

test("IItem XML deserialization fail", () => {
  const instanceOrError = OurXmlization.fromXmlString("This is not XML.");
  expect(instanceOrError.error).not.toBeNull();
});

test(
  "IItem XML deserialization fail via " +
  "itemFromXmlString",
  () => {
    const instanceOrError = OurXmlization.itemFromXmlString(
      "This is not XML."
    );
    expect(instanceOrError.error).not.toBeNull();
  }
);

